// Adapted from the local development runner. No provider records are read.
import fs from 'node:fs';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';

const root = fileURLToPath(new URL('../', import.meta.url));
const cases = JSON.parse(fs.readFileSync(new URL('cases.json', import.meta.url)));
const conditions = ['baseline', 'full', 'without-unicode', 'without-escaping', 'default'];
const hash = data => crypto.createHash('sha256').update(data).digest('hex');
const grade = (actual, expected) => actual === expected;
// Exact canonical output is the contract; whitespace must not be trimmed.
assert(grade('"a,b",z\n', '"a,b",z\n'));
assert(!grade('a,b,z\n', '"a,b",z\n'));
assert(!grade('a  \n', 'a\n'));
assert(!grade('a\n\n', 'a\n'));
// Valid but noncanonical CSV is intentionally outside this byte-level grader.
assert(!grade('"a",z\n', 'a,z\n'));

function verify(record) {
  assert.deepEqual(record.cases, cases);
  assert.deepEqual(record.conditions, conditions);
  assert.equal(record.results.length, conditions.length * cases.length);
  for (const [i, row] of record.results.entries()) {
    const task = cases[Math.floor(i / conditions.length)];
    assert.equal(row.case, task.id);
    assert.equal(row.condition, conditions[i % conditions.length]);
    const infra = row.status !== 0 || row.error !== null;
    assert.equal(row.infrastructureFailure, infra);
    assert.equal(row.pass, !infra && grade(row.actual, task.expected));
  }
}
const [mode, destination] = process.argv.slice(2);
if (!destination || !['--run', '--replay'].includes(mode)) {
  throw Error('Usage: node test/study.mjs --run|--replay FILE');
}
let record;
if (mode === '--replay') {
  record = JSON.parse(fs.readFileSync(destination));
} else {
  // Freeze the current production source and inputs before any execution.
  const source = fs.readFileSync(`${root}app.mjs`);
  const fixtureHash = hash(fs.readFileSync(new URL('cases.json', import.meta.url)));
  const results = cases.flatMap(task => conditions.map(condition => {
    const args = [`${root}app.mjs`, JSON.stringify(task.input)];
    if (condition !== 'default') args.push(condition);
    const run = spawnSync(process.execPath, args, {encoding: 'utf8', cwd: root, timeout: 5000});
    const error = run.error?.message ?? null;
    const infrastructureFailure = run.status !== 0 || error !== null;
    return {case: task.id, condition, actual: run.stdout, stderr: run.stderr,
      status: run.status, error, infrastructureFailure,
      pass: !infrastructureFailure && grade(run.stdout, task.expected)};
  }));
  assert.equal(hash(fs.readFileSync(`${root}app.mjs`)), hash(source));
  assert.equal(hash(fs.readFileSync(new URL('cases.json', import.meta.url))), fixtureHash);
  record = {source: 'app.mjs', sourceSha256: hash(source), fixtureSha256: fixtureHash,
    runnerSha256: hash(fs.readFileSync(fileURLToPath(import.meta.url))),
    runtime: process.version, cases, conditions, results};
  verify(record);
  fs.writeFileSync(destination, JSON.stringify(record, null, 2) + '\n', {flag: 'wx'});
}
verify(record);
for (const task of cases) {
  console.log(task.id + ': ' + record.results.filter(r => r.case === task.id)
    .map(r => `${r.condition}=${r.infrastructureFailure ? 'INFRA' : r.pass ? 'PASS' : 'FAIL'}`).join(' '));
}
if (record.results.some(r => r.infrastructureFailure ||
    (['full', 'default'].includes(r.condition) && !r.pass))) process.exitCode = 1;
EOF
node test/study.mjs --run test/results.json
node test/study.mjs --replay test/results.json

