import fs from 'node:fs';
import {execFileSync,spawnSync} from 'node:child_process';
const cases=JSON.parse(fs.readFileSync('test/cases.json'));
const initial=execFileSync('git',['show','HEAD:app.mjs'],{encoding:'utf8'});
const prepared=initial.replace("|| 'baseline'", "|| 'full'");
const rows=[];
for(const [revision,source] of [['initial',initial],['prepared',prepared]]) {
 for(const task of cases) for(const mode of ['default','full']) {
 const args=['--eval',source,'placeholder',JSON.stringify(task.input)];
 if(mode==='full') args.push('full');
 const r=spawnSync(process.execPath,args,{encoding:'utf8'});
 rows.push({revision,case:task.id,mode,status:r.status,actual:r.stdout,pass:r.status===0&&r.stdout===task.expected});
 }
}
fs.writeFileSync('.local/historical-comparison.json',JSON.stringify(rows,null,2));
console.log(rows.map(r=>`${r.revision} ${r.case} ${r.mode} ${r.pass}`).join('\n'));
EOF
